+          <button
+            type="button"
+            className="flex h-8 w-full items-center gap-2 rounded-lg px-1.5 text-left text-sm hover:bg-muted/70 focus-visible:bg-muted/70 focus-visible:outline-none"
+            onClick={createCollection}
+          >
+            <AppSidebarPlusIcon className="size-4" />
+            {query.trim()
+              ? t("documentMenu.newCollectionNamed", {
+                  collection: query.trim(),
+                })
