+export type DataViewPresentation =
+  | EmbeddedDataViewPresentation
+  | GalleryDataViewPresentation
+  | ListDataViewPresentation
+  | TableDataViewPresentation
+  | WallDataViewPresentation;
+
+export type WorkspaceDataView = {
