+function hasValidDataViewIdentity(view: Partial<WorkspaceDataView>): boolean {
+  return (
+    isNonEmptyString(view.id) &&
+    isNonEmptyString(view.workspaceId) &&
+    isNonEmptyString(view.creatorId) &&
+    isNonEmptyString(view.name)
+  );
