+  const validWidth =
+    column.width === undefined ||
+    (Number.isFinite(column.width) && (column.width ?? 0) > 0);
+  return (
+    isNonEmptyString(column.id) &&
+    isNonEmptyString(column.label) &&
+    isNonEmptyString(column.propertyId) &&
+    typeof column.visible === "boolean" &&
