+  if (
+    source.valueType === target.valueType &&
+    source.multiple === target.multiple
+  ) {
+    return "compatible";
+  }
+  if (
+    source.multiple === target.multiple &&
+    ((textualTypes.has(source.valueType) && textualTypes.has(target.valueType)) ||
