+          reason: "No matching target property exists.",
+          resolution: { kind: "unresolved" },
+          sourcePropertyId: definition.id,
+          sourceValue: propertyValues[definition.id],
+        };
+      }
+      const compatibility = comparePropertyDefinitions(
+        definition,
+        suggestedTarget,
