+            ? { kind: "map", targetPropertyId: suggestedTarget.id }
+            : { kind: "unresolved" },
+        sourcePropertyId: definition.id,
+        sourceValue: propertyValues[definition.id],
+        suggestedTargetPropertyId: suggestedTarget.id,
